/**
 * The states a share can be in, and how each one is worded, coloured and drawn. One list for
 * every app and every layout: the phone and the desktop show the same word in the same colour
 * for the same thing. Nothing in this file draws, so it can be tested without a screen.
 *
 * An app works out WHICH state a share is in (only it knows its engine); this file decides
 * everything a person sees about that state.
 */

/**
 * - `active`: the files are here and can be opened; a share of your own that others can get.
 * - `sharing`: someone is taking the files from this device right now.
 * - `downloading`: the files are arriving right now.
 * - `starting`: the other side has been found and the download is about to move.
 * - `waiting`: nobody to download from yet. It carries on by itself when someone appears.
 * - `paused`: the person stopped it. It never carries on by itself.
 * - `inactive`: switched off. Not shared, not arriving.
 * - `choose`: the list of files is here and none has been asked for yet.
 * - `attention`: it cannot carry on until the person does something (`note` says what).
 */
export type ShareStateKind =
  | 'active'
  | 'sharing'
  | 'downloading'
  | 'starting'
  | 'waiting'
  | 'paused'
  | 'inactive'
  | 'choose'
  | 'attention';

export const SHARE_STATE_KINDS: readonly ShareStateKind[] = [
  'active',
  'sharing',
  'downloading',
  'starting',
  'waiting',
  'paused',
  'inactive',
  'choose',
  'attention',
];

/**
 * The colour of the words. The same four names as the tone of a file in `FileViews`.
 *
 * - `good` (green): finished and available.
 * - `busy` (amber): not finished yet, whether it is moving, waiting or paused.
 * - `plain` (grey): switched off.
 * - `bad` (red): needs the person.
 */
export type ShareStateTone = 'good' | 'busy' | 'plain' | 'bad';

/**
 * How the progress bar is drawn. Three states share the amber words, and the bar is what tells
 * them apart at a glance.
 *
 * - `moving`: the amber-to-green gradient. Bytes are moving, or about to.
 * - `holding`: flat faint amber. Waiting for the other side; it will move by itself.
 * - `stopped`: flat grey. Paused by the person; it will not move by itself.
 */
export type ShareBarLook = 'moving' | 'holding' | 'stopped';

export type ShareBar = { look: ShareBarLook; /** 0 to 1. */ value: number };

/** The one button that changes a download's state: "Pause" while it may run, "Resume" once paused. */
export type ShareToggle = 'pause' | 'resume';

export type ShareStateInput = {
  kind: ShareStateKind;
  /** 0 to 100 of the files asked for, or null when it is not known or there is nothing to count. */
  percent?: number | null;
  /** For `attention`: the few words that say what is wrong ("Not enough space"). */
  note?: string | null;
};

export type ShareStateView = {
  kind: ShareStateKind;
  /** The one short line: "Downloading 48%", "Active". */
  label: string;
  /** The same in fewer letters, for a grid tile: the number is dropped where a picture shows it. */
  shortLabel: string;
  tone: ShareStateTone;
  /** The progress bar to draw under the line, or null for none. */
  bar: ShareBar | null;
  /** Drawn fainter. Only a share that is switched off. */
  dim: boolean;
  /** The pause or resume button this state offers, or null for neither. */
  toggle: ShareToggle | null;
};

function wholePercent(percent: number | null | undefined): number | null {
  if (percent == null || !Number.isFinite(percent)) return null;
  return Math.round(Math.min(100, Math.max(0, percent)));
}

const TONES: Record<ShareStateKind, ShareStateTone> = {
  active: 'good',
  sharing: 'busy',
  downloading: 'busy',
  starting: 'busy',
  waiting: 'busy',
  paused: 'busy',
  inactive: 'plain',
  choose: 'busy',
  attention: 'bad',
};

const WORDS: Record<ShareStateKind, string> = {
  active: 'Active',
  sharing: 'Sharing',
  downloading: 'Downloading',
  starting: 'Starting',
  waiting: 'Waiting',
  paused: 'Paused',
  inactive: 'Inactive',
  choose: 'Choose files',
  attention: 'Needs you',
};

/** The word for a state with no number: what a filter, a legend or a setting calls it. */
export function shareStateWord(kind: ShareStateKind): string {
  return WORDS[kind];
}

export function shareStateTone(kind: ShareStateKind): ShareStateTone {
  return TONES[kind];
}

/** Pause while a download may still run by itself; Resume once the person has paused it. */
export function shareStateToggle(kind: ShareStateKind): ShareToggle | null {
  if (kind === 'paused') return 'resume';
  if (kind === 'downloading' || kind === 'starting' || kind === 'waiting') return 'pause';
  return null;
}

/**
 * Everything a person sees about one state. One state at a time, never a chain of them: no
 * "Saved · Sharing", no "Paused · sender offline". The reason behind a state belongs in a
 * details window, not in the line.
 */
export function describeShareState(input: ShareStateInput): ShareStateView {
  const { kind } = input;
  const percent = wholePercent(input.percent);
  const word = WORDS[kind];
  let label = word;
  let shortLabel = word;
  let bar: ShareBar | null = null;

  switch (kind) {
    case 'downloading':
      // Always a number, even 0%: the number is the proof that it is alive.
      label = `${word} ${percent ?? 0}%`;
      bar = { look: 'moving', value: (percent ?? 0) / 100 };
      break;
    case 'sharing':
      if (percent != null) {
        label = `${word} ${percent}%`;
        // The grid has no pie for an upload, so its number stays.
        shortLabel = label;
        bar = { look: 'moving', value: percent / 100 };
      }
      break;
    case 'starting':
      if (percent != null) bar = { look: 'moving', value: percent / 100 };
      break;
    case 'waiting':
    case 'paused':
      // A number only once something has arrived: "Paused 0%" says nothing "Paused" does not.
      if (percent != null && percent > 0) label = `${word} ${percent}%`;
      if (percent != null) bar = { look: kind === 'waiting' ? 'holding' : 'stopped', value: percent / 100 };
      break;
    case 'attention': {
      const note = (input.note ?? '').trim();
      if (note) {
        label = note;
        shortLabel = note;
      }
      break;
    }
    default:
      break;
  }

  return {
    kind,
    label,
    shortLabel,
    tone: TONES[kind],
    bar,
    dim: kind === 'inactive',
    toggle: shareStateToggle(kind),
  };
}

// ---------------------------------------------------------------------------------------------
// Colours
// ---------------------------------------------------------------------------------------------

/** The colours of the progress bar. An app passes its own; these are the dark defaults. */
export type ShareBarColors = {
  /** The empty part. */
  track: string;
  /** The gradient of a bar that is moving, left to right. */
  from: string;
  to: string;
  /** A bar that is waiting. */
  holding: string;
  /** A bar the person paused. */
  stopped: string;
};

/** Pearkit's own dark theme: `warning` to `primary`, on an 8% white track. */
export const DARK_SHARE_BAR_COLORS: ShareBarColors = {
  track: 'rgba(255,255,255,0.08)',
  from: '#fbbf24',
  to: '#a6ce39',
  holding: 'rgba(251,191,36,0.55)',
  stopped: 'rgba(255,255,255,0.34)',
};

/** A hex colour made see-through. Any other way of writing a colour is handed back as it is. */
export function fadeColor(color: string, alpha: number): string {
  const hex = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(color.trim())?.[1];
  if (!hex) return color;
  const full = hex.length === 3 ? hex.replace(/./g, (c) => c + c) : hex;
  const part = (at: number) => parseInt(full.slice(at, at + 2), 16);
  return `rgba(${part(0)},${part(2)},${part(4)},${Math.min(1, Math.max(0, alpha))})`;
}

/**
 * The bar's colours from an app's own status colours, so the bar and the words always agree:
 * the gradient runs from the app's amber to its green.
 */
export function shareBarColorsFrom(app: { busy: string; good: string; track?: string; stopped?: string }): ShareBarColors {
  return {
    track: app.track ?? DARK_SHARE_BAR_COLORS.track,
    from: app.busy,
    to: app.good,
    holding: fadeColor(app.busy, 0.55),
    stopped: app.stopped ?? DARK_SHARE_BAR_COLORS.stopped,
  };
}

/** The filled part of a bar: two stops for the gradient, the same colour twice for a flat one. */
export function shareBarFill(look: ShareBarLook, colors: ShareBarColors = DARK_SHARE_BAR_COLORS): [string, string] {
  if (look === 'holding') return [colors.holding, colors.holding];
  if (look === 'stopped') return [colors.stopped, colors.stopped];
  return [colors.from, colors.to];
}

/** How wide the filled part is, as a share of the track, held between nothing and all of it. */
export function shareBarWidth(value: number): number {
  if (!Number.isFinite(value)) return 0;
  return Math.min(1, Math.max(0, value));
}
